"""Database connection pool for the checkout service."""

import queue

POOL_SIZE = 2  # reduced from 20 in the latest release
ACQUIRE_TIMEOUT_SECONDS = 1.5


class ConnectionPool:
    """Fixed-size pool; callers block until a connection is free."""

    def __init__(self, size: int = POOL_SIZE) -> None:
        self._free: queue.Queue[object] = queue.Queue(maxsize=size)
        for _ in range(size):
            self._free.put(object())

    def acquire(self) -> object:
        try:
            return self._free.get(timeout=ACQUIRE_TIMEOUT_SECONDS)
        except queue.Empty as exc:
            raise TimeoutError("database connection pool exhausted") from exc

    def release(self, connection: object) -> None:
        self._free.put(connection)


def acquire_connection(pool: ConnectionPool) -> object:
    """Return a database connection or raise when the pool is exhausted."""
    return pool.acquire()


def close_pool(pool: ConnectionPool) -> None:
    while not pool._free.empty():
        pool._free.get_nowait()


def healthcheck(pool: ConnectionPool) -> bool:
    return not pool._free.empty()

