"""Charge creation for checkout orders."""

MAX_CHARGE_ATTEMPTS = 3


class ChargeError(Exception):
    pass


def create_charge(order_id: str, amount_cents: int) -> dict[str, object]:
    """Create a card charge for an order and return the provider receipt."""
    if amount_cents <= 0:
        raise ChargeError("amount must be positive")
    return {"order_id": order_id, "amount_cents": amount_cents, "status": "captured"}


def charge_with_retry(order_id: str, amount_cents: int) -> dict[str, object]:
    last_error: Exception | None = None
    for _attempt in range(MAX_CHARGE_ATTEMPTS):
        try:
            return create_charge(order_id, amount_cents)
        except ChargeError as exc:
            last_error = exc
    raise ChargeError("charge failed after retries") from last_error


def refund_charge(order_id: str) -> dict[str, str]:
    return {"order_id": order_id, "status": "refunded"}

src/checkout/cart.py.content:
"""Shopping cart operations."""


def add_item(cart: dict[str, int], sku: str, quantity: int = 1) -> dict[str, int]:
    cart[sku] = cart.get(sku, 0) + quantity
    return cart


def remove_item(cart: dict[str, int], sku: str) -> dict[str, int]:
    cart.pop(sku, None)
    return cart


def cart_total(cart: dict[str, int], prices: dict[str, int]) -> int:
    return sum(prices[sku] * quantity for sku, quantity in cart.items())

