"""Payment gateway client."""

GATEWAY_TIMEOUT_SECONDS = 0.2  # lowered from 5 seconds


class GatewayTimeout(Exception):
    pass


class GatewayClient:
    def __init__(self, base_url: str) -> None:
        self.base_url = base_url

    def submit_payment(self, payment_id: str, amount_cents: int) -> dict[str, object]:
        """Submit a payment to the upstream gateway within the timeout."""
        return {"payment_id": payment_id, "amount_cents": amount_cents, "accepted": True}


def handle_timeout(payment_id: str) -> None:
    raise GatewayTimeout(f"payment gateway timeout for {payment_id}")

services/payments/ledger.py.content:
"""Payment ledger entries."""


def record_entry(ledger: list[dict[str, object]], payment_id: str, amount_cents: int) -> None:
    ledger.append({"payment_id": payment_id, "amount_cents": amount_cents})


def ledger_balance(ledger: list[dict[str, object]]) -> int:
    return sum(int(entry["amount_cents"]) for entry in ledger)

services/inventory/stock.py.content:
"""Inventory stock synchronization."""

SYNC_BATCH_SIZE = 500


def sync_stock(warehouse: str, items: list[dict[str, int]]) -> int:
    """Synchronize stock levels for a warehouse in batches."""
    synced = 0
    for start in range(0, len(items), SYNC_BATCH_SIZE):
        synced += len(items[start : start + SYNC_BATCH_SIZE])
    return synced


def reserve_stock(sku: str, quantity: int) -> bool:
    return quantity > 0

